    function statusHTML() {
      const m=live().monitor||{},s=live().stats||{};
      const labels={application_not_running:'Aplicativo fora de execução',monitoring_disabled:'Monitoramento desativado',integration_changed:'Integração alterada',disconnected:'Desconexão',partial_history_import:'Histórico parcial',capture_queue_full:'Fila de captura cheia',offline:'Sem internet',session_expired:'Sessão expirada'};
      const gaps=[...(m.openGap?[m.openGap]:[]),...(m.gaps||[])].slice(0,6);
      const periods=gaps.length?'<details class="buscas-gaps"><summary>Períodos com captura incompleta</summary>'+gaps.map(g=>'<p>'+e(fmt(g.startedAt))+' a '+e(g.endedAt?fmt(g.endedAt):'agora')+' · '+e(labels[g.reason]||g.reason||'Eventos indisponíveis')+'</p>').join('')+'</details>':'';
      return '<div class="buscas-status"><div><span class="status-dot '+e((typeof m.connection==='string'?m.connection:m.connection?.state)||ctx.data()?.connection?.state||'disconnected')+'"></span><strong>'+e(({disabled:'Monitoramento desativado',paused:'Captura pausada',monitoring:'Monitorando mensagens recebidas',disconnected:'Desconectado — captura interrompida'})[m.status]||'Monitoramento desativado')+'</strong><small>Início: '+e(fmt(m.startedAt))+' · Última sincronização: '+e(fmt(m.lastSyncAt||m.lastCaptureAt))+' · '+e(s.offers??s.totalOffers??0)+' ofertas</small></div><span class="soft-text">'+e(m.queueSize||0)+' na fila · '+e((m.gaps||[]).length)+' lacuna(s) registrada(s)</span></div>'+periods;
    }
    function render() {
      const p=perms();
      if(!live().authorized&&!ctx.auth()?.user?.isOwner)return '<div class="panel"><div class="panel-body">Você não tem autorização para o módulo BUSCAS.</div></div>';
      const tabs=[['query','Pesquisar',allowed('search')],['offers','Ofertas capturadas',allowed('view')],['history','Histórico',allowed('history')],['setup','Configurações',allowed('manage')||allowed('filters')],['destinations','Destinatários e envios',allowed('manage')],['people','Autorizados',allowed('manage')],['data','Dados e limpeza',allowed('manage')]].filter(t=>t[2]);
      if(!tabs.some(t=>t[0]===state.tab))state.tab=tabs[0]?.[0]||'query';
      const views={query:renderQuery,offers:renderOffers,history:renderHistory,setup:renderSetup,destinations:renderDestinations,people:renderPeople,data:renderData};
      return '<div id="buscas-page" data-buscas-tab="'+e(state.tab)+'"><div class="page-heading"><div><div class="eyebrow">OFERTAS DOS SEUS FORNECEDORES</div><h1>BUSCAS</h1><p class="subtitle">Capture anúncios recebidos e compare preços, preservando o texto e as condições de cada oferta.</p></div>'+btn('reload','Atualizar','small')+'</div><div id="buscas-monitor-status">'+statusHTML()+'</div><div class="warning-note buscas-coverage">A captura depende do aplicativo conectado. O histórico não é considerado completo: mensagens anteriores, períodos desconectados e eventos não recebidos podem criar lacunas.</div><div class="buscas-tabs">'+tabs.map(([id,label])=>btn('tab',label,state.tab===id?'primary':'ghost',id)).join('')+'</div>'+(views[state.tab]?.()||'')+'</div>';
    }
    async function load() {
      const epoch=state.epoch,actor=ctx.auth()?.user?.id;const response=await safeCall('searchesState');
      if(epoch!==state.epoch||actor!==ctx.auth()?.user?.id)return;
      state.settings=state.dirty?state.settings:response.settings;
      if(ctx.data())ctx.data().buscas=response;
      if(state.tab==='offers'&&allowed('view')){const result=await safeCall('searchOffers',{confidence:state.offerConfidence||undefined,includeReview:!state.offerConfidence,includeUnavailable:true,limit:50,offset:state.offset});if(epoch===state.epoch&&actor===ctx.auth()?.user?.id)state.offers=result;}
      if(state.tab==='history'&&allowed('history')){const result=await safeCall('searchHistory',{limit:50,offset:state.offset});if(epoch===state.epoch&&actor===ctx.auth()?.user?.id)state.history=result;}
      if(state.tab==='people'&&allowed('manage')){const result=await safeCall('searchAuthorizations');if(epoch===state.epoch&&actor===ctx.auth()?.user?.id)state.authorizations=arr(result);}
      if(state.tab==='destinations'&&allowed('manage')){const result=await safeCall('searchRecipientStatus');if(epoch===state.epoch&&actor===ctx.auth()?.user?.id)state.recipientStatus=result;}
    }
    function shouldPreserveDOM() {
      const page=$('#buscas-page');
      if(!page||page.dataset.buscasTab!==state.tab)return false;
      return state.dirty || state.queryDirty || !!document.activeElement?.closest('#buscas-query-form, #buscas-settings-form, #buscas-simulation-form');
    }
    function updateStatus(){const el=$('#buscas-monitor-status');if(el)el.innerHTML=statusHTML();}
